/* ---------- helpers ---------- */
function h(tag, attrs, kids){ var el = document.createElement(tag); if (attrs) Object.keys(attrs).forEach(function(k){ var v = attrs[k]; if (v === null || v === undefined || v === false) return; if (k === "text") el.textContent = v; else el.setAttribute(k, v === true ? "" : v); }); (kids || []).forEach(function(c){ if (c === null || c === undefined) return; el.appendChild(typeof c === "string" ? document.createTextNode(c) : c); }); return el; }
function clear(el){ while (el.firstChild) el.removeChild(el.firstChild); }
function can(roles){ if (me.roles.indexOf("super_admin") > -1) return true; return (roles || []).some(function(r){ return me.roles.indexOf(r) > -1; }); }
function fmtDT(iso){ return iso ? new Date(iso).toLocaleString("en-GB", { timeZone: TZ, day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) : ""; }
function fmtD(s){ return s ? new Date(String(s).length > 10 ? s : s + "T12:00:00Z").toLocaleDateString("en-GB", { timeZone: "UTC", day: "2-digit", month: "short", year: "numeric" }) : ""; }
function lagosInput(iso){ if (!iso) return ""; var p = new Intl.DateTimeFormat("en-CA", { timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date(iso)), o = {}; p.forEach(function(x){ o[x.type] = x.value; }); return o.year + "-" + o.month + "-" + o.day + "T" + o.hour + ":" + o.minute; }
function fromLagos(v){ return v ? v + ":00+01:00" : null; }
function todayYmd(){ return PLAN_ymd(); }
function PLAN_ymd(){ return window.TSC_PLAN.ymd(window.TSC_PLAN.lagosParts(new Date(), TZ)); }
function msg(kind, text){ return h("div", { "class": "msg " + kind, text: text, role: kind === "err" ? "alert" : "status" }); }
function badge(v){ var s = String(v == null ? "" : v), cls = /^(published|approved|active|completed|yes|true|closed)$/.test(s) ? "ok" : /(rejected|overdue|false)/.test(s) ? "bad" : ""; return h("span", { "class": "badge " + cls, text: s.replace(/_/g, " ") }); }
function waDigits(p){ var d = String(p || "").replace(/[^\d+]/g, ""); if (d.charAt(0) === "+") return d.slice(1); if (d.indexOf("00") === 0) return d.slice(2); if (d.charAt(0) === "0") return "234" + d.slice(1); return d; }
function staffName(id){ var s = staff.filter(function(x){ return x.id === id; })[0]; return s ? (s.full_name || "Staff") : ""; }
function csv(rows, cols){ function q(v){ if (v === null || v === undefined) v = ""; if (typeof v === "object") v = JSON.stringify(v); v = String(v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; } return [cols.join(",")].concat(rows.map(function(r){ return cols.map(function(c){ return q(r[c]); }).join(","); })).join("\n"); }
