/* ---------- API ---------- */
function saveSession(s){ session = s; if (s) sessionStorage.setItem("tsc_admin", JSON.stringify(s)); else sessionStorage.removeItem("tsc_admin"); }
function authCall(path, body){ return fetch(SBU + "/auth/v1/" + path, { method: "POST", headers: { apikey: KEY, "Content-Type": "application/json" }, body: JSON.stringify(body) }).then(function(r){ return r.json().then(function(j){ if (!r.ok) throw new Error(j.error_description || j.msg || j.message || "Request failed"); return j; }); }); }
function toSession(j){ return { access_token: j.access_token, refresh_token: j.refresh_token, expires_at: Date.now() + (j.expires_in || 3600) * 1000, user: j.user }; }
function ensureFresh(){ if (!session) return Promise.reject(new Error("signed out")); if (session.expires_at - Date.now() > 60000) return Promise.resolve(); return authCall("token?grant_type=refresh_token", { refresh_token: session.refresh_token }).then(function(j){ saveSession(toSession(j)); }).catch(function(){ saveSession(null); showLogin("Your session expired. Please sign in again."); throw new Error("session expired"); }); }
