function count(table, filter){ return ensureFresh().then(function(){ return fetch(SBU + "/rest/v1/" + table + "?select=id" + (filter ? "&" + filter : ""), { headers: { apikey: KEY, Authorization: "Bearer " + session.access_token, Prefer: "count=exact", Range: "0-0" } }); }).then(function(r){ if (!r.ok) throw new Error("no access"); var cr = r.headers.get("content-range") || ""; return parseInt(cr.split("/")[1], 10) || 0; }); }
function upload(file){ return ensureFresh().then(function(){ return fetch(SBU + "/storage/v1/object/gallery/" + file.path, { method: "POST", headers: { apikey: KEY, Authorization: "Bearer " + session.access_token, "Content-Type": file.blob.type || "image/jpeg" }, body: file.blob }); }).then(function(r){ if (!r.ok) return r.text().then(function(t){ throw new Error("Upload failed: " + t); }); return SBU + "/storage/v1/object/public/gallery/" + file.path; }); }
function shrink(file, max, quality){ return new Promise(function(resolve, reject){ var img = new Image(), url = URL.createObjectURL(file); img.onload = function(){ var s = Math.min(1, max / Math.max(img.width, img.height)), c = document.createElement("canvas"); c.width = Math.round(img.width * s); c.height = Math.round(img.height * s); c.getContext("2d").drawImage(img, 0, 0, c.width, c.height); c.toBlob(function(b){ URL.revokeObjectURL(url); b ? resolve(b) : reject(new Error("Could not process image")); }, "image/jpeg", quality); }; img.onerror = function(){ reject(new Error("That file is not a readable image")); }; img.src = url; }); }

/* ---------- login ---------- */
function showLogin(note){
  clear(app);
  var em = h("input", { type: "email", id: "em", required: true, autocomplete: "username" }), pw = h("input", { type: "password", id: "pw", required: true, autocomplete: "current-password" }), out = h("div");
  var form = h("form", null, [h("div", { "class": "field" }, [h("label", { "for": "em", text: "Email" }), em]), h("div", { "class": "field" }, [h("label", { "for": "pw", text: "Password" }), pw]), out, h("button", { "class": "btn gold", type: "submit", text: "Sign in" })]);
  var reset = h("button", { "class": "btn ghost sm", type: "button", text: "Forgot password?", style: "margin-top:1rem" });
  reset.addEventListener("click", function(){ if (!em.value) { clear(out); out.appendChild(msg("info", "Type your email above first.")); return; } authCall("recover", { email: em.value }).then(function(){ clear(out); out.appendChild(msg("ok", "If that email has an account, a reset link has been sent.")); }).catch(function(e){ clear(out); out.appendChild(msg("err", e.message)); }); });
  form.addEventListener("submit", function(e){ e.preventDefault(); clear(out); authCall("token?grant_type=password", { email: em.value.trim(), password: pw.value }).then(function(j){ saveSession(toSession(j)); boot(); }).catch(function(err){ out.appendChild(msg("err", /invalid/i.test(err.message) ? "Incorrect email or password." : err.message)); }); });
  app.appendChild(h("div", { "class": "login" }, [h("h1", { text: "TSC Administration" }), h("p", { text: "Authorised church personnel only.", style: "color:var(--muted);margin:.3rem 0 0" }), note ? msg("info", note) : null, form, reset, h("p", { style: "margin-top:1.4rem" }, [h("a", { href: "index.html", text: "Back to the website" })])]));
}
function logout(){ var t = session && session.access_token; saveSession(null); if (t) fetch(SBU + "/auth/v1/logout", { method: "POST", headers: { apikey: KEY, Authorization: "Bearer " + t } }).catch(function(){}); showLogin("You have been signed out."); }

